// comment: the rest of the line is consumed and reported as end-of-line.
export function skipWsComment(line, i) {
  i = skipWs(line, i)
  if (i < line.length && (line[i] === '#' || line[i] === ';')) return line.length
  return i
}

export function parseBasicString(line, i, lineNo) {
  // assumes line[i] === '"'
  i++
  let out = ''
  while (true) {
    if (i >= line.length) throw err('unterminated string', lineNo)
    const c = line[i]
    if (c === '"') return { value: out, i: i + 1 }
    if (c === '\\') {
      i++
      if (i >= line.length) throw err('unterminated string', lineNo)
      const e = line[i]
      switch (e) {
        case '"':
          out += '"'
          i++
          break
        case '\\':
          out += '\\'
          i++
          break
        case 'n':
          out += '\n'
          i++
          break
        case 't':
          out += '\t'
          i++
          break
        case 'r':
          out += '\r'
          i++
          break
        case '0':
          out += '\0'
          i++
          break
        case 'u': {
          const hex = line.slice(i + 1, i + 5)
          if (hex.length === 4 && /^[0-9A-Fa-f]{4}$/.test(hex)) {
            out += String.fromCharCode(parseInt(hex, 16))
            i += 5
          } else {
            throw err('invalid escape \\u', lineNo)
          }
          break
        }
        default:
          throw err(`invalid escape \\${e}`, lineNo)
      }
    } else {
      out += c
      i++
    }
  }
