export function parseLiteralString(line, i, lineNo) {
  // assumes line[i] === "'"
  i++
  const start = i
  while (true) {
    if (i >= line.length) throw err('unterminated string', lineNo)
    if (line[i] === "'") return { value: line.slice(start, i), i: i + 1 }
    i++
  }
