  if (i < line.length && line[i] === '"') return parseBasicString(line, i, lineNo)
  if (i < line.length && line[i] === "'") return parseLiteralString(line, i, lineNo)
  const start = i
  while (i < line.length && NAME_CHAR.test(line[i])) i++
  if (i === start) throw err('expected a name', lineNo)
  return { value: line.slice(start, i), i }
}

