  const parts = []
  i = skipWs(line, i)
  let r = parseName(line, i, lineNo)
  parts.push(r.value)
  i = r.i
  while (true) {
    const j = skipWs(line, i)
    if (j < line.length && line[j] === '.') {
      i = skipWs(line, j + 1)
      r = parseName(line, i, lineNo)
      parts.push(r.value)
      i = r.i
    } else {
      break
    }
  }
  return { parts, i }
