  const an = Array.from(a, (ch) => ch.codePointAt(0))
  const bn = Array.from(b, (ch) => ch.codePointAt(0))
  const len = Math.min(an.length, bn.length)
  for (let i = 0; i < len; i++) {
    if (an[i] !== bn[i]) return an[i] - bn[i]
  }
  return an.length - bn.length
}
"}

