{"file_path":"src/value.js","content":"/**
 * Parses a value (scalar, array or inline table) starting at some
 * position in a line. Returns { node, i } where node is a tagged tree
 * node (see tree.js for the shapes) and i is the index just past the
 * value's text.
 */

import { err, skipWsComment, parseBasicString, parseLiteralString, parseDottedName } from './lex.js'
import { assignDotted } from './tree.js'

function isTerminator(ch) {
  return ch === ' ' || ch === '\t' || ch === ',' || ch === ']' || ch === '}'
}

const INT_RE = /^[+-]?\d+(_\d+)*$/
const FLOAT_RE = /^[+-]?\d+(_\d+)*(\.\d+(_\d+)*)?([eE][+-]?\d+(_\d+)*)?$/

function classifyNumber(raw) {
  if (INT_RE.test(raw)) return 'integer'
  if (FLOAT_RE.test(raw)) return 'float'
  return null
}

export function parseValue(line, i, lineNo, basePath) {
  i = skipWsComment(line, i)
  if (i >= line.length || line[i] === ',' || line[i] === ']' || line[i] === '}') {
    throw err('expected a value', lineNo)
  }
  const c = line[i]
  if (c === '"') {
    const r = parseBasicString(line, i, lineNo)
    return { node: { kind: 'string', value: r.value }, i: r.i }
  }
  if (c === "'") {
    const r = parseLiteralString(line, i, lineNo)
    return { node: { kind: 'string', value: r.value }, i: r.i }
  }
  if (c === '[') return parseArrayValue(line, i, lineNo, basePath)
  if (c === '{') return parseInlineTableValue(line, i, lineNo, basePath)

  const start = i
  while (i < line.length && !isTerminator(line[i])) i++
  const raw = line.slice(start, i)
  if (raw === 'true') return { node: { kind: 'boolean', value: true }, i }
  if (raw === 'false') return { node: { kind: 'boolean', value: false }, i }
  const kind = classifyNumber(raw)
  if (kind === 'integer') {
    let t = raw.replace(/_/g, '')
    if (t[0] === '+') t = t.slice(1)
    return { node: { kind: 'integer', value: BigInt(t) }, i }
  }
  if (kind === 'float') {
    const t = raw.replace(/_/g, '')
    return { node: { kind: 'float', value: Number(t) }, i }
  }
  throw err(`invalid value ${raw}`, lineNo)
}

function parseArrayValue(line, i, lineNo, basePath) {
  i++ // skip '['
  const items = []
  let idx = 0
  while (true) {
    i = skipWsComment(line, i)
    if (i >= line.length) throw err('unterminated array', lineNo)
    if (line[i] === ']') return { node: { kind: 'array', items }, i: i + 1 }
    const r = parseValue(line, i, lineNo, basePath.concat([idx]))
    items.push(r.node)
    i = r.i
    idx++
    i = skipWsComment(line, i)
    if (i >= line.length) throw err('unterminated array', lineNo)
    if (line[i] === ',') {
      i++
      continue
    }
    if (line[i] === ']') return { node: { kind: 'array', items }, i: i + 1 }
    throw err('unterminated array', lineNo)
  }
}

function parseInlineTableValue(line, i, lineNo, basePath) {
  i++ // skip '{'
  const table = { kind: 'table', entries: new Map(), explicit: false }
  i = skipWsComment(line, i)
  if (i >= line.length) throw err('unterminated inline table', lineNo)
  if (line[i] === '}') return { node: table, i: i + 1 }
  while (true) {
    i = skipWsComment(line, i)
    if (i >= line.length) throw err('unterminated inline table', lineNo)
    const nameRes = parseDottedName(line, i, lineNo)
    i = skipWsComment(line, nameRes.i)
    if (i >= line.length || line[i] !== '=') throw err('expected = in an inline table', lineNo)
    i = skipWsComment(line, i + 1)
    const valRes = parseValue(line, i, lineNo, basePath.concat(nameRes.parts))
    i = valRes.i
    assignDotted(table, nameRes.parts, valRes.node, basePath, lineNo)
    i = skipWsComment(line, i)
    if (i >= line.length) throw err('unterminated inline table', lineNo)
    if (line[i] === ',') {
      i++
      continue
    }
    if (line[i] === '}') return { node: table, i: i + 1 }
    throw err('unterminated inline table', lineNo)
  }
}
"}

