{"file_path":"src/tree.js","content":"/**
 * The document tree and the operations that mutate it: assigning a
 * dotted key inside a table, and resolving a `[name]`/`[[name]]`
 * header against the root table.
 *
 * Node shapes:
 *   { kind: 'table', entries: Map<string, Node>, explicit: boolean }
 *   { kind: 'arraytable', items: Node[] }        // items are 'table' nodes
 *   { kind: 'array', items: Node[] }
 *   { kind: 'string'|'boolean', value }
 *   { kind: 'integer', value: BigInt }
 *   { kind: 'float', value: number }
 */

import { err, pathToString } from './lex.js'

export function newRoot() {
  return { kind: 'table', entries: new Map(), explicit: true }
}

// Step into (or create) the table named `name` inside `container`,
// following the "walking an array of tables uses its last element"
// rule. `curPath` already has `name` pushed on for error reporting.
function enterOrCreateTable(container, name, lineNo, curPath) {
  if (container.entries.has(name)) {
    const existing = container.entries.get(name)
    if (existing.kind === 'table') return { table: existing, extraToken: null }
    if (existing.kind === 'arraytable') {
      const idx = existing.items.length - 1
      return { table: existing.items[idx], extraToken: idx }
    }
    throw err(`${pathToString(curPath)} is not a table`, lineNo)
  }
  const nt = { kind: 'table', entries: new Map(), explicit: false }
  container.entries.set(name, nt)
  return { table: nt, extraToken: null }
}

// Assign `node` at the dotted path `keyParts` inside `table`, creating
// intermediate tables as the dots walk through. `basePathTokens` is the
// absolute path (from the document root) of `table` itself.
export function assignDotted(table, keyParts, node, basePathTokens, lineNo) {
  let cur = table
  const curPath = basePathTokens.slice()
  for (let idx = 0; idx < keyParts.length - 1; idx++) {
    const name = keyParts[idx]
    curPath.push(name)
    const res = enterOrCreateTable(cur, name, lineNo, curPath)
    cur = res.table
    if (res.extraToken !== null) curPath.push(res.extraToken)
  }
  const last = keyParts[keyParts.length - 1]
  curPath.push(last)
  if (cur.entries.has(last)) {
    throw err(`key ${pathToString(curPath)} is defined twice`, lineNo)
  }
  cur.entries.set(last, node)
}

// Resolve a `[name]` (isArray = false) or `[[name]]` (isArray = true)
// header against `root`, creating tables on the way. Returns
// { table, path } where `path` is the absolute path of the resolved
// (now current) table.
export function resolveHeaderTable(root, parts, isArray, lineNo) {
  let cur = root
  const curPath = []
  for (let idx = 0; idx < parts.length - 1; idx++) {
    const name = parts[idx]
    curPath.push(name)
    const res = enterOrCreateTable(cur, name, lineNo, curPath)
    cur = res.table
    if (res.extraToken !== null) curPath.push(res.extraToken)
  }
  const name = parts[parts.length - 1]
  curPath.push(name)

  if (!isArray) {
    if (cur.entries.has(name)) {
      const existing = cur.entries.get(name)
      if (existing.kind !== 'table') throw err(`${pathToString(curPath)} is not a table`, lineNo)
      if (existing.explicit) throw err(`table ${pathToString(curPath)} is defined twice`, lineNo)
      existing.explicit = true
      return { table: existing, path: curPath }
    }
    const nt = { kind: 'table', entries: new Map(), explicit: true }
    cur.entries.set(name, nt)
    return { table: nt, path: curPath }
  }

  if (cur.entries.has(name)) {
    const existing = cur.entries.get(name)
    if (existing.kind !== 'arraytable') {
      throw err(`${pathToString(curPath)} is not an array of tables`, lineNo)
    }
    const nt = { kind: 'table', entries: new Map(), explicit: true }
    existing.items.push(nt)
    const idx = existing.items.length - 1
    return { table: nt, path: curPath.concat([idx]) }
  }
  const nt = { kind: 'table', entries: new Map(), explicit: true }
  const at = { kind: 'arraytable', items: [nt] }
  cur.entries.set(name, at)
  return { table: nt, path: curPath.concat([0]) }
}
"}

