{"file_path":"src/format.js","content":"/**
 * Renders a parsed document tree either as canonical JSON or as a
 * flat list of `<path> <type>` lines.
 */

import { pathToString, cmpCodePoint } from './lex.js'

function sortedKeys(table) {
  return [...table.entries.keys()].sort(cmpCodePoint)
}

function valueToJSON(node, indent) {
  switch (node.kind) {
    case 'table':
      return tableToJSON(node, indent)
    case 'arraytable':
      return arrayLikeToJSON(node.items, indent)
    case 'array':
      return arrayLikeToJSON(node.items, indent)
    case 'string':
      return JSON.stringify(node.value)
    case 'boolean':
      return node.value ? 'true' : 'false'
    case 'integer':
      return node.value.toString()
    case 'float':
      return JSON.stringify(node.value)
    default:
      throw new Error(`unknown node kind ${node.kind}`)
  }
}

function tableToJSON(node, indent) {
  const keys = sortedKeys(node)
  if (keys.length === 0) return '{}'
  const pad = '  '.repeat(indent + 1)
  const closePad = '  '.repeat(indent)
  const parts = keys.map(
    (k) => `${pad}${JSON.stringify(k)}: ${valueToJSON(node.entries.get(k), indent + 1)}`
  )
  return `{\n${parts.join(',\n')}\n${closePad}}`
}

function arrayLikeToJSON(items, indent) {
  if (items.length === 0) return '[]'
  const pad = '  '.repeat(indent + 1)
  const closePad = '  '.repeat(indent)
  const parts = items.map((it) => pad + valueToJSON(it, indent + 1))
  return `[\n${parts.join(',\n')}\n${closePad}]`
}

export function toJSON(root) {
  return valueToJSON(root, 0) + '\n'
}

function typeOf(node) {
  switch (node.kind) {
    case 'table':
      return 'table'
    case 'arraytable':
      return 'array'
    case 'array':
      return 'array'
    default:
      return node.kind
  }
}

function walk(node, pathTokens, out) {
  out.push(`${pathToString(pathTokens)} ${typeOf(node)}`)
  if (node.kind === 'table') {
    for (const k of sortedKeys(node)) walk(node.entries.get(k), pathTokens.concat([k]), out)
  } else if (node.kind === 'arraytable' || node.kind === 'array') {
    node.items.forEach((it, idx) => walk(it, pathTokens.concat([idx]), out))
  }
}

export function toKeys(root) {
  const out = []
  for (const k of sortedKeys(root)) walk(root.entries.get(k), [k], out)
  return out.length ? out.join('\n') + '\n' : ''
}
"}

